egui_glow = { version = "0.37.0", path = "crates/egui_glow", default-features = false }
egui_inspection = { version = "0.37.0", path = "crates/egui_inspection", default-features = false }
egui_kittest = { version = "0.37.0", path = "crates/egui_kittest", default-features = false }
egui_system_font_provider = { version = "0.37.0", path = "crates/egui_system_font_provider", default-features = false }
eframe = { version = "0.37.0", path = "crates/eframe", default-features = false }

accesskit = "0.25.1"
accesskit_consumer = "0.39.1"
accesskit_winit = "0.34.1"
ahash = { version = "0.8.12", default-features = false, features = [
  "no-rng", # we don't need DOS-protection, so we let users opt-in to it instead
  "std",
] }
android_logger = "0.15.1"
arboard = { version = "3.7", default-features = false }
backtrace = "0.3.76"
bitflags = "2.13"
bytemuck = "1.25"
cint = "0.3.1"
color-hex = "0.2.0"
criterion = { version = "0.8.2", default-features = false }
dify = { version = "0.8.0", default-features = false }
directories = "6.0"
document-features = "0.2.12"
ehttp = { version = "0.7.1", default-features = false }
enum-map = "3.1"
env_logger = { version = "0.11.11", default-features = false }
font-types = { version = "0.12.7", default-features = false, features = ["std"] }
fontique = { version = "0.12.0", default-features = false, features = [
  "system",
  "fontconfig-dlopen", # Load libfontconfig at runtime, so builds don't need its headers
] }
glow = "0.17.0" # Can't update to 0.18: wgpu 30's wgpu-hal pins glow 0.17, so bumping splits it into two versions
glutin = { version = "0.32.3", default-features = false }
